import{_ as e,o as d,c as r,a2 as o}from"./chunks/framework.CkKL3Me7.js";const p=JSON.parse('{"title":"Time Tracking Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools/time.md","filePath":"reference/tools/time.md"}'),s={name:"reference/tools/time.md"};function n(a,t,i,c,l,h){return d(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="time-tracking-tools" tabindex="-1">Time Tracking Tools <a class="header-anchor" href="#time-tracking-tools" aria-label="Permalink to &quot;Time Tracking Tools&quot;">​</a></h1><hr><h2 id="log_time" tabindex="-1">log_time <a class="header-anchor" href="#log_time" aria-label="Permalink to &quot;log_time {#log_time}&quot;">​</a></h2><p>Record hours on a project.</p><p><strong>Writes to</strong>: <code>01. Time Entries</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>string</td><td>✅</td><td>Always the sender&#39;s Slack ID</td></tr><tr><td><code>project</code></td><td>string</td><td>✅</td><td>Project name (must match exactly)</td></tr><tr><td><code>task</code></td><td>string</td><td>✅</td><td>Task type — Development, Design, QA, etc.</td></tr><tr><td><code>hours</code></td><td>string</td><td>✅</td><td>Format: <code>&quot;4h 30m&quot;</code></td></tr><tr><td><code>date</code></td><td>string</td><td></td><td><code>YYYY-MM-DD</code> — defaults to today</td></tr><tr><td><code>notes</code></td><td>string</td><td></td><td>Optional context</td></tr><tr><td><code>slack_user_id</code></td><td>string</td><td></td><td>Log for another user — Manager/Owner only</td></tr><tr><td><code>person</code></td><td>string</td><td></td><td>Name-based lookup (less reliable than <code>slack_user_id</code>)</td></tr></tbody></table><p><strong>Business rules:</strong></p><ul><li>Task is always required — VERA will ask if missing</li><li>User can only log for themselves unless Manager/Owner</li><li>When logging for an <code>@mention</code>, use <code>slack_user_id</code> not <code>person</code></li><li>Returns entry <code>id</code> on success: &quot;Logged 4h on Nike Rebrand (Development) (ID: 42)&quot;</li></ul><p><strong>Example:</strong></p><blockquote><p>&quot;Log 4h 30m on Nike Rebrand for development&quot; &quot;Log 2 hours for @alice on Acme project — design&quot;</p></blockquote><hr><h2 id="get_time_entries" tabindex="-1">get_time_entries <a class="header-anchor" href="#get_time_entries" aria-label="Permalink to &quot;get_time_entries {#get_time_entries}&quot;">​</a></h2><p>Retrieve and filter time entries.</p><p><strong>Reads from</strong>: <code>01. Time Entries</code>, <code>02. Projects</code>, <code>03. Users</code>, <code>05. Tasks</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>string</td><td>Controls what data is returned</td></tr><tr><td><code>slack_user_id</code></td><td>string</td><td>Filter by person (Slack ID — preferred)</td></tr><tr><td><code>person</code></td><td>string</td><td>Filter by person name</td></tr><tr><td><code>project_name</code></td><td>string</td><td>Filter by project</td></tr><tr><td><code>task_name</code></td><td>string</td><td>Filter by task type</td></tr><tr><td><code>start_date</code></td><td>string</td><td><code>YYYY-MM-DD</code> — range start</td></tr><tr><td><code>end_date</code></td><td>string</td><td><code>YYYY-MM-DD</code> — range end</td></tr></tbody></table><p><strong>Permission rules:</strong></p><ul><li>Owners see all entries</li><li>Managers see entries for their assigned projects</li><li>Users see only their own entries</li></ul><p><strong>Note:</strong> When querying for an <code>@mention</code> (e.g. &quot;show @alice&#39;s time&quot;), always pass <code>slack_user_id</code> rather than <code>person</code>. Name matching can fail if display names differ from stored names.</p><hr><h2 id="hours_this_week" tabindex="-1">hours_this_week <a class="header-anchor" href="#hours_this_week" aria-label="Permalink to &quot;hours_this_week {#hours_this_week}&quot;">​</a></h2><p>Sum of hours logged this week for a user.</p><p><strong>Reads from</strong>: <code>01. Time Entries</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>string</td><td></td></tr><tr><td><code>slack_user_id</code></td><td>string</td><td>For querying another user (Manager/Owner)</td></tr></tbody></table><p>Week boundaries are calculated in the tenant&#39;s configured timezone.</p><hr><h2 id="edit_entry" tabindex="-1">edit_entry <a class="header-anchor" href="#edit_entry" aria-label="Permalink to &quot;edit_entry {#edit_entry}&quot;">​</a></h2><p>Update the hours or notes on a time entry.</p><p><strong>Updates</strong>: <code>01. Time Entries</code> (full row rewrite A:H)</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>string</td><td>✅</td><td></td></tr><tr><td><code>id</code></td><td>integer</td><td>✅</td><td>Entry ID (from log confirmation or get_time_entries)</td></tr><tr><td><code>new_hours</code></td><td>string</td><td></td><td>New hours value — format <code>&quot;4h 30m&quot;</code></td></tr><tr><td><code>new_notes</code></td><td>string</td><td></td><td>New notes</td></tr></tbody></table><p><strong>Permission</strong>: Owners can edit any entry. Users can only edit their own.</p><hr><h2 id="delete_entry" tabindex="-1">delete_entry <a class="header-anchor" href="#delete_entry" aria-label="Permalink to &quot;delete_entry {#delete_entry}&quot;">​</a></h2><p>Permanently delete a time entry.</p><p><strong>Deletes from</strong>: <code>01. Time Entries</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>string</td><td>✅</td><td></td></tr><tr><td><code>id</code></td><td>integer</td><td>✅</td><td>Entry ID to delete</td></tr></tbody></table><p><strong>Permission</strong>: Owners can delete any entry. Users can only delete their own.</p><blockquote><p>Deletion is permanent. There is no undo. VERA will confirm the action before deleting.</p></blockquote>',42)])])}const m=e(s,[["render",n]]);export{p as __pageData,m as default};
